function onSaveCopiesAndFolders() {
  SaveFolderSettings(
    gFccRadioElemChoice,
    "doFcc",
    Ci.nsMsgFolderFlags.SentMail,
    gFccFolderWithDelim,
    "msgFccAccountPicker",
    "msgFccFolderPicker",
    "identity.fccFolderURI",
    "identity.fccFolderPickerMode"
  );

  SaveFolderSettings(
    gArchivesRadioElemChoice,
    "messageArchives",
    Ci.nsMsgFolderFlags.Archive,
    gArchivesFolderWithDelim,
    "msgArchivesAccountPicker",
    "msgArchivesFolderPicker",
    "identity.archivesFolderURI",
    "identity.archivesFolderPickerMode"
  );

  SaveFolderSettings(
    gDraftsRadioElemChoice,
    "messageDrafts",
    Ci.nsMsgFolderFlags.Drafts,
    gDraftsFolderWithDelim,
    "msgDraftsAccountPicker",
    "msgDraftsFolderPicker",
    "identity.draftsFolderURI",
    "identity.draftsFolderPickerMode"
  );

  SaveFolderSettings(
    gTmplRadioElemChoice,
    "messageTemplates",
    Ci.nsMsgFolderFlags.Templates,
    gTemplatesFolderWithDelim,
    "msgTemplatesAccountPicker",
    "msgTemplatesFolderPicker",
    "identity.templatesFolderURI",
    "identity.templatesFolderPickerMode"
  );
}

// Save folder settings and radio element choices
function SaveFolderSettings(
  radioElemChoice,
  radioGroupId,
  folderFlag,
  defaultFolderSuffix,
  accountPickerId,
  folderPickerId,
  folderElementId,
  folderPickerModeId
) {
  let formElement = document.getElementById(folderElementId);
  let uri;

  if (
    radioElemChoice == "0" ||
    !document.getElementById(folderPickerId).value
  ) {
    // Default or revert to default if no folder chosen.
    radioElemChoice = "0";
    uri = document.getElementById(accountPickerId).folder?.URI;
    if (uri) {
      const rootFolder = MailServices.folderLookup.getFolderForURL(uri);
      const flaggedFolder = rootFolder.getFolderWithFlags(folderFlag);
      // Create Folder URI.
      uri = flaggedFolder?.URI ?? uri + defaultFolderSuffix;
    }
  } else if (radioElemChoice == "1") {
    uri = document.getElementById(folderPickerId).folder?.URI;
  } else {
    dump("Error saving folder preferences.\n");
    return;
  }

  formElement.setAttribute("value", uri);

  formElement = document.getElementById(folderPickerModeId);
  formElement.setAttribute("value", radioElemChoice);
}
